def evaluate(current_reputation, observation, my_history, round_num):
    # Decaying learning rate: starts at 0.3, declines to 0.05
    alpha = max(0.05, 0.3 - round_num * 0.005)
    # Map actions to less extreme targets
    if observation["action"] == "A":
        target = 0.8   # cooperative, but not perfect
    else:
        target = -0.6  # defect, but not too harsh
    new_rep = (1 - alpha) * current_reputation + alpha * target
    return max(-1.0, min(1.0, new_rep))


def decide(recipient_reputation, round_num, my_history):
    # Compute own average cooperation from history
    if my_history:
        my_avg = sum(1 for act in my_history if act) / len(my_history)
    else:
        my_avg = 0.5
    # Base threshold grows slowly over rounds: from 0.2 to 0.3
    base = 0.2 + 0.1 * (round_num / 15.0)
    # Adjust based on own past cooperation: raise threshold if I am cooperative,
    # lower it if I am not (to encourage more cooperation from others)
    adjusted = base + 0.1 * (my_avg - 0.5)
    adjusted = max(0.0, min(1.0, adjusted))
    return recipient_reputation >= adjusted

