def decide(recipient_reputation, round_num, my_history):
    # Slightly higher initial threshold, slower decay, different floor
    base_threshold = max(0.3, 0.5 - round_num * 0.02)

    # Own average of past actions (own history)
    if my_history:
        true_count = sum(1 for act in my_history if act is True)
        my_average = true_count / len(my_history)
    else:
        my_average = 0.5

    # Adjust threshold: more cooperative -> lower threshold (easier to cooperate)
    # This reverses the original direction to see if the norm prefers it
    adjusted = base_threshold - 0.2 * (my_average - 0.5)
    adjusted = max(0.0, min(1.0, adjusted))

    # Additionally, be unforgiving to very bad reputations once the round allows it
    if round_num > 3 and recipient_reputation < -0.5:
        return False

    return recipient_reputation >= adjusted

