    base_threshold = max(0.4, 0.6 - round_num * 0.03)

    if my_history:
        true_count = sum(1 for act in my_history if act is True)
        my_average = true_count / len(my_history)
    else:
        my_average = 0.5

    # Adjust threshold: more cooperative -> increase threshold (harder to cooperate) - opposite of original
    adjusted = base_threshold + 0.2 * (my_average - 0.5)
    adjusted = max(0.0, min(1.0, adjusted))

